head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst00700";
scwin.discloureArr = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — searchType

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "disclosureTypeArr01", attr: "toolTip", fn: function () { return String((dma_pageContext.get("rsnClssNm") ?? "")); } },
        { childId: "disclosureTypeArr01", attr: "__items", fn: function () { return [[String((dma_pageContext.get("frmCdString") ?? "")), ""]]; } },
        { childId: "disclosureTypeArr02", attr: "toolTip", fn: function () { return String((dma_pageContext.get("rsnClssNm") ?? "")); } },
        { childId: "disclosureTypeArr02", attr: "__items", fn: function () { return [[String((dma_pageContext.get("frmCdString") ?? "")), ""]]; } },
        { childId: "disclosureTypeArr05", attr: "toolTip", fn: function () { return String((dma_pageContext.get("rsnClssNm") ?? "")); } },
        { childId: "disclosureTypeArr05", attr: "__items", fn: function () { return [[String((dma_pageContext.get("frmCdString") ?? "")), ""]]; } },
        { childId: "disclosureTypeArr15", attr: "toolTip", fn: function () { return String((dma_pageContext.get("rsnClssNm") ?? "")); } },
        { childId: "disclosureTypeArr15", attr: "__items", fn: function () { return [[String((dma_pageContext.get("frmCdString") ?? "")), ""]]; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_searchType", fn: function () { return String(String((dma_pageContext.get("searchType") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { $c.util.getComponent("dma_pageContext").set("c", String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDatesOnlyPeriod( "1 ') */
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        const searchType = ($c.util.getComponent("dma_fnDownloadReq").get("searchType") || '');
        if (searchType === '01') {
            (($c.util.getComponent('A00')) && ($c.util.getComponent('A00')).addClass ? ($c.util.getComponent('A00')).addClass("active") : console.error('[sdd] addClass 미지원 컴포넌트: A00'));
            (($c.util.getComponent('C04')) && ($c.util.getComponent('C04')).addClass ? ($c.util.getComponent('C04')).addClass("active") : console.error('[sdd] addClass 미지원 컴포넌트: C04'));
            (($c.util.getComponent('D13')) && ($c.util.getComponent('D13')).addClass ? ($c.util.getComponent('D13')).addClass("active") : console.error('[sdd] addClass 미지원 컴포넌트: D13'));
            $('input:checkbox[name=disclosureTypeArr01]').attr("checked", "checked");
            $('input:checkbox[name=disclosureTypeArr05]').attr("checked", "checked");
            $('input:checkbox[name=disclosureTypeArr15]').attr("checked", "checked");
        } else {
            if (searchType === '02') {
                (($c.util.getComponent('B01')) && ($c.util.getComponent('B01')).addClass ? ($c.util.getComponent('B01')).addClass("active") : console.error('[sdd] addClass 미지원 컴포넌트: B01'));
                $('input:checkbox[name=disclosureTypeArr02]').attr("checked", "checked");
            } else {
                if (searchType === '03') {
                    (($c.util.getComponent('E14')) && ($c.util.getComponent('E14')).addClass ? ($c.util.getComponent('E14')).addClass("active") : console.error('[sdd] addClass 미지원 컴포넌트: E14'));
                    $('input:checkbox[name=disclosureTypeArr11]').attr("checked", "checked");
                }
            }
        }
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst00700.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.discloureArr =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst00700' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst00700.onpageload' });
    }
};

