 * @description checked Box 처리
 * @param {*} dName dName
 * @param {*} yn yn
 * @returns {void}
 * @hidden N
 */
scwin.checkedBox = function (dName, yn) {
    if (dName.length === null) {
        dName.checked = yn;
    } else {
        for (let j = 0; j < dName.length; j++) {
            dName[j].checked = yn;
        }
    }
};

