/**
 * @method
 * @name disclosureSetting
 * @description disclosure Setting 처리
 * @param {*} code code
 * @returns {void}
 * @hidden N
 */
scwin.disclosureSetting = function (code) {
    const get_name = $('input:checkbox[name=disclosureTypeArr' + code + ']');
    const set_name = $('input:hidden[name=pDisclosureType' + code + ']');
    const checkVal = $('input:hidden[name=disclosureType' + code + ']');
    const length = get_name.length;
    let check_setting = "";
    if (length === null) {
        if (get_name.checked === true) {
            check_setting += get_name.value + "|";
        }
    } else {
        for (let j = 0; j < length; j++) {
            if (get_name[j].checked === true) {
                check_setting += get_name[j].value + "|";
            }
        }
    }
    set_name.val(check_setting);
    checkVal.val(check_setting);
};

/**
 * @method
 * @name fnCorpType
 * @description fn Corp Type 처리
 * @param {*} val val
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnCorpType = async function (val) {
    if ($c.num.isNumber(val.getValue()) === true) {
        if (val.getValue().length < 6 || val.getValue().length > 7) {
            await $c.win.alert("종목코드를 정확히 입력해 주세요.\n종목코드는 6자리 입니다.");
            val.setValue("");
            $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "");
            return false;
        } else {
            $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "number");
        }
    } else {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "char");
    }
};

