/**
 * @method
 * @name fnSetDisclosureType
 * @description fn Set Disclosure Type 처리
 * @param {Object} obj 컴포넌트
 * @param {*} chk_name chk_name
 * @returns {void}
 * @hidden N
 */
scwin.fnSetDisclosureType = function (obj, chk_name) {
    const $btn = $('#' + obj + '');
    const $sel = $('#' + obj.substring(0, 1) + '');
    const dis = $sel.css('display');
    const bcss = $btn.attr("class");
    const cnt = $("input[name=" + chk_name + "]:checked").length;
    if (dis === 'none') {
        $sel.css("display", "");
        if (!$btn.hasClass("active")) {
            $btn.addClass("active");
        }
    } else {
        $sel.css("display", "none");
        if (cnt === 0) {
            $btn.removeClass("active");
            $btn.css("display", "none");
            $btn.css("display", "");
        } else {
            if (!$btn.hasClass("active")) {
                $btn.addClass("active");
            }
        }
    }
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    scwin.disclosure_window_all_close();
    scwin.disclosureAllSetting();
    const searchForm = $("#searchForm");
    if (!$c.date.isDate(($c.util.getComponent("cal_fromDate").getValue() || ''))) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate(($c.util.getComponent("cal_toDate").getValue() || ''))) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        00;
        return;
    }
    if (($c.util.getComponent("cal_fromDate").getValue() || '') !== "" && ($c.util.getComponent("cal_toDate").getValue() || '') !== "") {
        if (!($c.date.diffDate(($c.util.getComponent("cal_fromDate").getValue() || ''), ($c.util.getComponent("cal_toDate").getValue() || '')) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    if ($c.date.addYear($c.util.getComponent('cal_fromDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_toDate').getValue(), 0)) {
        await $c.win.alert("조회기간은  3년 이내만 가능합니다.");
        return;
    }
    if ($(document).find("select[id=ipt_currentPageSize]").val() !== null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchBondCorpDisclosureSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "searchbondcorpdisclosure_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
    const searchType = (String(((dma_pageContext.get("searchType") ?? "")) === null ? '' : ((dma_pageContext.get("searchType") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("searchType") ?? "")) === null ? '' : ((dma_pageContext.get("searchType") ?? ""))));
    if (searchType === "") {
        if ($('input:checkbox[id=ipt_bfrDsclsType]').is(":checked")) {
            scwin.fnClearDsclsType();
        }
    }
};

